const hoy = new Date();
const hace60 = new Date(hoy);
hace60.setDate(hoy.getDate() - 60);

function fmt(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

const desde = `${fmt(hace60)}%2B00:00:00`;
const hasta = `${fmt(hoy)}%2B23:59:59`;

return [
  {
    json: {
      rango: `${desde}_${hasta}`,
      url: `https://www.comprasestatales.gub.uy/consultas/rss/tipo-pub/ALL/tipo-fecha/PUB/orden/ORD_PUB/tipo-orden/DESC/rango-fecha/${desde}_${hasta}`
    }
  }
];

// Recibe lo que venga del XML node
const input = $input.all().map((x) => x.json);

function clean(text) {
  return String(text || "")
    .replace(/<br\s*\/?>/gi, " | ")
    .replace(/&nbsp;/g, " ")
    .replace(/&sol;/g, "/")
    .replace(/&Uacute;/g, "Ú")
    .replace(/&Oacute;/g, "Ó")
    .replace(/&Iacute;/g, "Í")
    .replace(/&Eacute;/g, "É")
    .replace(/&Aacute;/g, "Á")
    .replace(/&Ntilde;/g, "Ñ")
    .replace(/&ntilde;/g, "ñ")
    .replace(/\s+/g, " ")
    .trim();
}

function extractFechaHoraApertura(descLimpia) {
  const re = /Recepci(?:ó|o)n de ofertas hasta:\s*([0-3]?\d\/[01]?\d\/\d{4})\s+(\d{2}:\d{2})\s*h?s?/i;
  const m = descLimpia.match(re);
  if (!m) return { fecha_apertura: null, hora_apertura: null };
  const [, ddmmyyyy, hhmm] = m;
  const [dd, mm, yyyy] = ddmmyyyy.split("/").map(Number);
  const fecha = `${yyyy}-${String(mm).padStart(2, "0")}-${String(dd).padStart(2, "0")}`;
  return { fecha_apertura: fecha, hora_apertura: hhmm };
}

function splitPubDate(pubDate) {
  if (!pubDate) return { fecha_publicacion: null, hora_publicacion: null };
  const d = new Date(pubDate);
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  const hh = String(d.getHours()).padStart(2, "0");
  const mi = String(d.getMinutes()).padStart(2, "0");
  return {
    fecha_publicacion: `${yyyy}-${mm}-${dd}`,
    hora_publicacion: `${hh}:${mi}`,
  };
}

let itemsRaw = [];
if (input.length === 1 && input[0]?.rss?.channel?.item) {
  itemsRaw = Array.isArray(input[0].rss.channel.item) ? input[0].rss.channel.item : [input[0].rss.channel.item];
} else {
  itemsRaw = input;
}

const out = itemsRaw.map((src) => {
  const title = src.title ?? src?.json?.title ?? "";
  const link = src.link ?? src?.json?.link ?? "";
  const pub = src.pubDate ?? src?.json?.pubDate ?? "";
  const descHtml = src.description ?? src["content:encoded"] ?? src?.json?.description ?? "";

  const descLimpia = clean(descHtml);
  const { fecha_apertura, hora_apertura } = extractFechaHoraApertura(descLimpia);
  const { fecha_publicacion, hora_publicacion } = splitPubDate(pub);

  let id = null;
  const match = link.match(/id\/([A-Za-z0-9]+)/i);
  if (match) id = match[1];

  return {
    json: {
      id,
      titulo: clean(title),
      descripcion: descLimpia,
      fecha_apertura,
      hora_apertura,
      fecha_publicacion,
      hora_publicacion,
      url_detalle: link,
    },
  };
});

out.forEach((item) => {
  if (!item.json.id) {
    const base = item.json.url_detalle || item.json.titulo || "sin_id";
    item.json.id = Buffer.from(base).toString("base64").slice(0, 10);
  }
});

return out;

const keywords = ["aluminio", "aberturas", "abertura", "ventana", "ventanas", "dvh", "blindex", "mampara", "mamparas", "vidrio", "vidrios", "cerramiento", "cerramientos", "fachada", "fachadas", "marco", "marcos", "puerta", "puertas", "carpintería metálica", "carpintería de aluminio", "estructura metálica", "reja", "rejas", "baranda", "barandas", "barandilla", "barandillas", "panel", "paneles", "cerramiento de obra", "muro cortina", "colocación de vidrios", "instalación de aberturas", "suministro de aberturas", "suministro de ventanas", "mantenimiento edilicio", "obra edilicia", "obras menores", "reparación edilicia", "sustitución de cubierta", "reforma edilicia"];

const exclude = ["curvispina", "pez", "peces", "animal", "animales", "insecto", "papel", "papelería", "bolígrafo", "resma", "sobre", "sobres", "impresión", "uniforme", "ropa", "textil", "camisa", "pantalón", "zapato", "calzado", "software", "computadora", "notebook", "monitor", "impresora", "sistema", "pantalla", "teclado", "mause", "tecnología", "electrónica", "alimento", "comida", "pan", "leche", "fruta", "verdura", "queso", "catering", "vianda", "pollo", "carne", "pescado", "aceite", "azúcar", "médico", "médica", "hospitalario", "medicamento", "farmacéutico", "inyección", "laboratorio", "quirúrgico", "jeringa", "cubierta", "cubiertas", "neumático", "neumáticos", "llanta", "vehículo", "camión", "escenario", "escenarios", "evento", "festival", "carpa", "led", "iluminación", "luz", "eléctrico", "eléctrica", "cable", "sobres con ventana", "ventana de sobre", "marco de pizarra", "pizarra"];

function esRelevante(item) {
  const texto = `${item.titulo} ${item.descripcion}`.toLowerCase();
  const hoy = new Date();
  hoy.setHours(0, 0, 0, 0);
  const apertura = item.fecha_apertura ? new Date(item.fecha_apertura) : null;
  const tieneClave = keywords.some((k) => texto.includes(k.toLowerCase()));
  const tieneExclusion = exclude.some((k) => texto.includes(k.toLowerCase()));
  const aperturaValida = apertura && apertura >= hoy;
  return tieneClave && !tieneExclusion && aperturaValida;
}

function diasHasta(fechaStr) {
  if (!fechaStr) return null;
  const hoy = new Date();
  hoy.setHours(0, 0, 0, 0);
  const fecha = new Date(fechaStr);
  const diff = (fecha - hoy) / (1000 * 60 * 60 * 24);
  return Math.floor(diff);
}

const items = $input.all().map((x) => x.json);

const relevantes = items
  .filter(esRelevante)
  .map((i) => {
    const dias = diasHasta(i.fecha_apertura);
    let urgencia;
    if (dias === null) urgencia = "desconocida";
    else if (dias <= 3) urgencia = "urgente";
    else if (dias <= 7) urgencia = "próximo";
    else if (dias <= 15) urgencia = "atención";
    else urgencia = "futuro";
    return { json: { ...i, dias_restantes: dias, urgencia } };
  })
  .sort((a, b) => {
    const da = new Date(`${a.json.fecha_publicacion}T${a.json.hora_publicacion}`);
    const db = new Date(`${b.json.fecha_publicacion}T${b.json.hora_publicacion}`);
    return db - da;
  });

return relevantes;

return items.map(item => {
  try {
    const data = JSON.parse(item.json.stdout || "{}");
    return {
      json: {
        id: data.id,
        aclaraciones: data.aclaraciones || [],
        archivos_adjuntos: data.archivos_adjuntos || [],
        items_extraidos: data.items_extraidos || []
      }
    };
  } catch (e) {
    return { json: { error: e.message, raw: item.json.stdout } };
  }
});

const sourceItems = $items("Merge Aclaraciones y Adjuntos + Llamados");
const output = [];

function limpiarNombre(nombre) {
  if (!nombre) return null;
  return String(nombre)
    .replace(/\s+/g, '')
    .replace(/\n/g, '')
    .replace(/\r/g, '')
    .trim();
}

for (const item of sourceItems) {
  const idLlamado = item.json.id;
  const adjuntos = item.json.archivos_adjuntos || [];
  for (const adj of adjuntos) {
    output.push({
      json: {
        id_llamado: idLlamado,
        nombre: limpiarNombre(adj.nombre),
        tipo: adj.tipo ?? null,
        archivo_url: adj.archivo_url ?? null,
        label: adj.label ?? null,
      },
    });
  }
}

return output;

const sourceItems = $items("Merge Aclaraciones y Adjuntos + Llamados");
const output = [];

for (const item of sourceItems) {
  const idLlamado = item.json.id;
  const aclaraciones = item.json.aclaraciones || [];
  for (const acl of aclaraciones) {
    output.push({
      json: {
        id_llamado: idLlamado,
        fecha: acl.fecha ?? null,
        hora: acl.hora ?? null,
        texto: acl.texto ?? null,
        archivo_url: acl.archivo_url ?? null,
      },
    });
  }
}

return output;

const sourceItems = $items("Merge Aclaraciones y Adjuntos + Llamados");
const output = [];

for (const item of sourceItems) {
  const id_llamado = item.json.id;
  const itemsExtraidos = item.json.items_extraidos || [];
  for (const texto of itemsExtraidos) {
    if (texto && typeof texto === 'string') {
      output.push({ json: { id_llamado, texto } });
    }
  }
}

return output;

const keywords = ["aluminio", "aberturas", "abertura", "ventana", "ventanas", "dvh", "blindex", "mampara", "mamparas", "vidrio", "vidrios", "cerramiento", "cerramientos", "fachada", "fachadas", "marco", "marcos", "puerta", "puertas", "carpintería metálica", "carpintería de aluminio", "estructura metálica", "reja", "rejas", "baranda", "barandas", "barandilla", "barandillas", "panel", "paneles", "cerramiento de obra", "muro cortina", "colocación de vidrios", "instalación de aberturas", "suministro de aberturas", "suministro de ventanas", "mantenimiento edilicio", "obra edilicia", "obras menores", "reparación edilicia", "sustitución de cubierta", "reforma edilicia"];

function normalizar(texto) {
  return String(texto || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

let items = $json.items_extraidos || [];
if (typeof items === "string") {
  try { items = JSON.parse(items); } catch { items = items.split(","); }
}

if (!Array.isArray(items) || items.length === 0) {
  return $json;
}

const textoItems = normalizar(items.join(" "));
const coincidencias = keywords.filter((kw) => textoItems.includes(normalizar(kw)));

if (coincidencias.length > 0) {
  $json.keywords_encontradas = coincidencias;
  return $json;
}

return null;

// Parsear la salida JSON del script bash
const stdout = $json.stdout || "{}";

try {
  const resultado = JSON.parse(stdout);
  return {
    json: {
      ...resultado,
      stdout_raw: stdout.substring(0, 1000) // Guardar primeros 1000 chars por si hay debug
    }
  };
} catch (e) {
  return {
    json: {
      error: "No se pudo parsear la salida del script",
      error_detalle: e.message,
      stdout_raw: stdout.substring(0, 2000)
    }
  };
}
